function validateLayoutFields(fields){if(!fields.length)throw Error('Informe pelo menos um campo.');const seen=new Set(),targets=new Set();for(let i=0;i<fields.length;i++){const f=fields[i];if(!f.campo_dataprep||!f.tipo)throw Error('Linha '+(i+2)+': preencha campo_dataprep e tipo. campo_produto é opcional.');if((f.campo_produto&&!/^[A-Z_][A-Z0-9_]*$/.test(f.campo_produto))||!/^[A-Z_][A-Z0-9_]*$/.test(f.campo_dataprep))throw Error('Linha '+(i+2)+': nomes devem conter letras, números e sublinhado, sem espaços.');if(f.campo_produto&&seen.has(f.campo_produto))throw Error('Campo de produto duplicado: '+f.campo_produto+'.');if(f.campo_produto)seen.add(f.campo_produto);if(targets.has(f.campo_dataprep))throw Error('Campo DataPrep duplicado: '+f.campo_dataprep+'.');targets.add(f.campo_dataprep);if(!layoutTypes.includes(f.tipo))throw Error('Tipo inválido para '+f.campo_produto+': '+f.tipo+'. Use STRING, INT, DECIMAL, DATE ou DATETIME.')}for(const f of fields)if(fields.some(other=>other!==f&&other.campo_produto===f.campo_dataprep))throw Error('Mapeamento ambíguo: '+f.campo_dataprep+' também é campo de produto em outro mapeamento.');return fields}
