async function loadProjectLayouts(){if(projectLayoutLoading)return;projectLayoutLoading=true;renderLayoutStorage();try{const response=await fetch('/api/layouts',{cache:'no-store'});if(!response.ok)throw Error('API local indisponível.');const payload=await response.json();if(payload.storage!=='project'||!Array.isArray(payload.layouts))throw Error('Resposta de layouts inválida.');const found=payload.layouts.map(parseLayoutRecord);projectLayoutIds=new Set(found.map(l=>l.id));for(const record of found){if(layouts.some(l=>l.id===record.id))layouts=layouts.map(l=>l.id===record.id?record:l);else layouts.push(record)}projectLayoutApiAvailable=true;saveLayouts();normalizeListRows(data);ensurePositiveRules(data);persist();render();refreshLayoutOptions();$('layoutStorageFeedback').textContent=found.length+' layout(s) lido(s) de layouts/.'+(payload.errors?.length?' Arquivos com problemas: '+payload.errors.join(' | '):'')}catch(e){projectLayoutApiAvailable=false;projectLayoutIds=new Set();$('layoutStorageFeedback').textContent='A pasta do projeto é lida automaticamente ao executar a versão local com npm start.'}finally{projectLayoutLoading=false;renderLayoutStorage()}}
