function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function dateSql(v){let m=/^(\d{2})\/(\d{2})\/(\d{4})$/.exec(v);if(!m)return null;let iso=`${m[3]}-${m[2]}-${m[1]}`,d=new Date(iso+'T00:00:00Z');return !Number.isNaN(+d)&&d.toISOString().slice(0,10)===iso?`DATE '${iso}'`:false}
