function missing(r){return keys.filter(k=>!String(r[k]??'').trim())}
function check(r,rows=data){let errors=fieldErrors(r);if(Object.keys(errors).length)return Object.entries(errors).map(([k,v])=>k+': '+v).join(' ');if(!/^[A-Za-z_][A-Za-z0-9_]*$/.test(r.campo))return 'Campo deve ser um identificador simples, sem espaços.';if(!ops.includes(normalizedOp(r.operador)))return 'Operador não suportado. Use IN, NOT IN, >, >=, <, <=, = ou <>.';let conflicts=divergent(r,rows);if(conflicts.length)return 'Transtype '+r.transtype+': valores divergentes em '+conflicts.join(', ')+'.';return ''}
function isPositiveGuard(r,attribute){return (fieldName(r.campo)===fieldName(attribute)||(resolveField(r.campo)&&resolveField(r.campo)?.campo_dataprep===resolveField(attribute)?.campo_dataprep))&&r.operador.trim()==='>'&&/^0+(?:[.,]0+)?$/.test(r.valor.trim())}
function ensurePositiveRules(rows){let added=0,skipped=[];const groups=new Map();for(const r of rows){const tt=r.transtype.trim();if(!tt)continue;if(!groups.has(tt))groups.set(tt,[]);groups.get(tt).push(r)}for(const [tt,group] of groups){const reference=group[0];if(meta.some(k=>!String(reference[k]??'').trim())||group.some(r=>meta.some(k=>r[k]!==reference[k]))){skipped.push(tt);continue}const attribute=reference.ATRIBUTO_VALOR;if(!group.some(r=>isPositiveGuard(r,attribute))){rows.push({...reference,campo:attribute,operador:'>',valor:'0',_valueType:'number'});added++}}return {added,skipped}}
function autoMessage(result){return result.added+' regra(s) de valor > 0 incluída(s).'+(result.skipped.length?' Corrija os dados contábeis dos Transtypes '+result.skipped.join(', ')+' para gerar a condição obrigatória.':'')}
function normalizedText(value){return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9\s]/g,'').replace(/\s+/g,' ').trim()}
function fieldName(value){return String(value??'').trim().toUpperCase()}
function normalizedOp(value){return String(value??'').trim().replace(/\s+/g,' ').toUpperCase()}
function readSqlLiteral(input){let date=/^DATE\s+'(\d{4})-(\d{2})-(\d{2})'/i.exec(input),match;if(date){let value=`${date[3]}/${date[2]}/${date[1]}`;if(!dateSql(value))throw Error('Literal DATE inválido.');return {value,type:'date',sql:dateSql(value),rest:input.slice(date[0].length)}}if((match=/^'((?:''|[^'])*)'/.exec(input))){let value=match[1].replace(/''/g,"'");return {value,type:'string',sql:match[0],rest:input.slice(match[0].length)}}if((match=/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?/.exec(input)))return {value:match[0],type:'number',sql:match[0],rest:input.slice(match[0].length)};throw Error("Use texto entre aspas simples, número ou DATE 'AAAA-MM-DD'.")}
function readSqlList(input){const wrapped=input.startsWith('(');let rest=(wrapped?input.slice(1):input).trimStart(),items=[];if(!rest||rest.startsWith(')'))throw Error('A lista de IN ou NOT IN não pode estar vazia.');while(rest){let item=readSqlLiteral(rest);items.push(item.sql);const trailing=item.rest;rest=trailing.trimStart();if(wrapped&&rest.startsWith(')'))return {value:items.join(', '),type:'list',rest:rest.slice(1)};if(!wrapped&&!rest.startsWith(','))return {value:items.join(', '),type:'list',rest:trailing};if(!rest.startsWith(','))throw Error('Separe os valores da lista com vírgulas.');rest=rest.slice(1).trimStart();if(!rest||rest.startsWith(')'))throw Error('Valor ausente após a vírgula.')}throw Error('Lista incompleta.')}
