function conditionValues(value){let text=String(value??'').trim();if(text.startsWith('(')&&text.endsWith(')'))text=text.slice(1,-1).trim();if(!text)throw Error('A lista não pode estar vazia.');let items=[],part='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==="'"){part+=ch;if(quoted&&text[i+1]==="'"){part+="'";i++}else quoted=!quoted}else if(ch===','&&!quoted){if(!part.trim())throw Error('Item vazio na lista.');items.push(part.trim());part=''}else part+=ch}if(quoted)throw Error('Aspas não fechadas na lista.');if(!part.trim())throw Error('Item vazio na lista.');items.push(part.trim());return items.map(v=>v.startsWith("'")&&v.endsWith("'")?v.slice(1,-1).replace(/''/g,"'"):v)}
function typedLiteral(value,type){let v=String(value??'').trim();if(['DATE','DATETIME'].includes(type))v=v.replace(/^(?:DATE|TIMESTAMP)\s+'([^']+)'$/i,'$1');if(type==='STRING'){v=normalizedText(v);if(!v)throw Error('Texto vazio após a limpeza.');return {display:v,sql:"'"+v+"'",type:'string'}}if(type==='INT'){if(!/^[+-]?\d+$/.test(v))throw Error('Valor "'+v+'" incompatível com INT: informe um número inteiro.');v=BigInt(v).toString();return {display:v,sql:v,type:'number'}}if(type==='DECIMAL'){v=v.replace(',','.');if(!/^[+-]?(?:\d+(?:\.\d+)?|\.\d+)$/.test(v))throw Error('Valor "'+v+'" incompatível com DECIMAL.');if(v.startsWith('.'))v='0'+v;if(v.startsWith('-.'))v='-0'+v.slice(1);if(v.startsWith('+.'))v='+0'+v.slice(1);return {display:v,sql:v,type:'number'}}if(type==='DATE'||type==='DATETIME'){let datePart=v,time='';if(type==='DATETIME'){let m=/^(.+?)[T ](\d{2}):(\d{2}):(\d{2})$/.exec(v);if(!m||+m[2]>23||+m[3]>59||+m[4]>59)throw Error('DATETIME deve conter data e hora válidas (AAAA-MM-DD HH:MM:SS).');datePart=m[1];time=`${m[2]}:${m[3]}:${m[4]}`}let iso=/^(\d{4})-(\d{2})-(\d{2})$/.exec(datePart);if(iso)datePart=`${iso[3]}/${iso[2]}/${iso[1]}`;const date=dateSql(datePart);if(!date)throw Error('Valor incompatível com '+type+': use DD/MM/AAAA ou AAAA-MM-DD.');if(type==='DATE')return {display:datePart,sql:date,type:'date'};const canonical=date.slice(6,-1)+' '+time;return {display:datePart+' '+time,sql:"'"+canonical+"'",type:'datetime'}}throw Error('Tipo do layout não suportado: '+type)}
function typedCondition(r){const field=resolveField(r.campo);if(!field)throw Error('Campo não localizado no layout: '+r.campo);const op=normalizedOp(r.operador),isList=['IN','NOT IN'].includes(op);const values=isList?conditionValues(r.valor):[r.valor],items=values.map(v=>typedLiteral(v,field.tipo));return {field,op,items,display:isList?items.map(v=>v.type==='string'?v.sql:v.display).join(', '):items[0].display,valueType:isList?'list':items[0].type}}
function normalizeListRows(rows){for(const r of rows){r.operador=normalizedOp(r.operador);for(const k of ['campo','ATRIBUTO_DATA','ATRIBUTO_VALOR'])r[k]=fieldName(r[k]);for(const k of ['EMPRESA','DEPARTAMENTO DEBITO','DEPARTAMENTO CREDITO'])if(!/^[\d./]+$/.test(String(r[k]??'')))r[k]=fieldName(r[k]);try{let typed=typedCondition(r);r.valor=typed.display;r._valueType=typed.valueType}catch{}}return rows}
