function parseSqlCell(input){let rest=String(input??'').trim(),conditions=[];if(!rest)throw Error('Regra obrigatória.');if(rest.length>50000)throw Error('Regra excede 50.000 caracteres.');while(rest){let head=/^([A-Za-z_][A-Za-z0-9_]*)\s*(NOT\s+IN\b|IN\b|<>|>=|<=|=|>|<)\s*/i.exec(rest);if(!head)throw Error('Condição inválida. Operadores aceitos: IN, NOT IN, >, >=, <, <=, = e <>. OR, funções e agrupamentos não são aceitos.');rest=rest.slice(head[0].length);let op=normalizedOp(head[2]),literal=['IN','NOT IN'].includes(op)?readSqlList(rest):readSqlLiteral(rest);conditions.push({campo:fieldName(head[1]),operador:op,valor:literal.value,_valueType:literal.type});rest=literal.rest;if(!rest.trim())break;let whitespace=/^\s+/.test(rest);rest=rest.trimStart();let connector=/^(AND|E)\b\s*/i.exec(rest);if(connector){let after=rest.slice(connector[0].length);if(!/^(?:<>|>=|<=|=|>|<|IN\b|NOT\s+IN\b)/i.test(after)){rest=after;if(!rest)throw Error('Conectivo sem uma condição após ele.');continue}}if(!whitespace||!/^[A-Za-z_][A-Za-z0-9_]*\s*(NOT\s+IN\b|IN\b|<>|>=|<=|=|>|<)/i.test(rest))throw Error('Separação inválida. Use AND, e, espaço ou quebra de linha entre condições completas.');}return conditions}
function expandSqlRows(sourceRows){let expanded=[];for(let i=0;i<sourceRows.length;i++){let row=sourceRows[i];try{const conditions=parseSqlCell(row.regra_sql);expanded.push(...conditions.map(c=>({...Object.fromEntries(meta.map(k=>[k,String(row[k]??'').trim()])),...c})));if(expanded.length>10000)throw Error('A expansão excede 10.000 condições.')}catch(e){throw Error(`Linha ${i+2}, Transtype ${row.transtype||'(vazia)'}: ${e.message}`)}}return expanded}
function expression(r){try{let t=typedCondition(r),id=t.field.campo_dataprep;return `${id} ${t.op} ${['IN','NOT IN'].includes(t.op)?'('+t.items.map(v=>v.sql).join(', ')+')':t.items[0].sql}`}catch(e){return '-- '+e.message}}
function sqlFor(rows){if(!['LK2','VP8'].includes(parameterType))return '-- Selecione o tipo de parametrização: LK2 ou VP8.';let errors=rows.map(r=>check(r,rows)).filter(Boolean);return errors.length?'-- Corrija os alertas para gerar a prévia SQL.':rows.map(r=>expression(r)).join('\nAND ')}
function persist(){saveCurrentProject();localStorage.setItem('conecta-contabil-v1',JSON.stringify({parameterType,serviceCode,rows:data,name:$('fileName').textContent}))}function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3500)}
function displayCell(r,k){const value=esc(presentationValue(r[k],k));if(!['EMPRESA','DEPARTAMENTO DEBITO','DEPARTAMENTO CREDITO'].includes(k))return value;const fixed=k==='EMPRESA'?/^\d{3}[./]\d{3}$/.test(r[k]):/^\d{5}$/.test(r[k]);const malformed=k==='EMPRESA'?/^[\d./]+$/.test(r[k]):/^\d+$/.test(r[k]);const type=fixed?'fixed':malformed?'invalid':'reference';const label=fixed?'Fixo':malformed?'Formato inválido':'Campo do layout';return `<span class="typed-value">${value}<span class="value-type ${type}">${label}</span></span>`}
for(const key of locationKeys)$(key).oninput=()=>{integrationLocations[key]=$(key).value;persist()};
$('serviceCode').oninput=()=>{const entered=$('serviceCode').value;serviceCode=entered.replace(/[^0-9]/g,'').slice(0,5);$('serviceCode').value=serviceCode;$('serviceCodeFeedback').textContent=entered!==serviceCode?'Use apenas números, com no máximo 5 dígitos.':'';persist()};
