const sharedLabels={transtype:'Transtype',DESCRICAO_TRANSTYPE:'Descrição Transtype',EMPRESA:'Empresa',ATRIBUTO_DATA:'Atributo data',ATRIBUTO_VALOR:'Atributo valor','DEPARTAMENTO DEBITO':'Departamento débito','DEPARTAMENTO CREDITO':'Departamento crédito','CONTA DEBITO':'Conta débito','CONTA CREDITO':'Conta crédito'};
const ttColumns=['transtype','DESCRICAO_TRANSTYPE','regra_sql','EMPRESA','ATRIBUTO_DATA','ATRIBUTO_VALOR','DEPARTAMENTO DEBITO','DEPARTAMENTO CREDITO','CONTA DEBITO','CONTA CREDITO'];
const tableState={sortKey:'transtype',direction:'asc',page:1,pageSize:10};
const tableCollator=new Intl.Collator('pt-BR',{numeric:true,sensitivity:'base'});
function sortValue(record,key){if(key==='pilot')return pilotTranstypes.has(record.tt)?'1':'0';if(key==='excluded')return excludedTranstypes.has(record.tt)?'1':'0';if(key==='regra_sql')return record.sql;if(key==='review')return record.errors.length?'Com alerta':'Sem alertas';if(key==='validation')return record.errors.join(' | ')||'Todos os campos preenchidos.';return attributeDisplayValue(record.base[key],key)}
function orderTts(records){return records.map((record,index)=>({record,index})).sort((a,b)=>{const comparison=tableCollator.compare(sortValue(a.record,tableState.sortKey),sortValue(b.record,tableState.sortKey));return comparison?(tableState.direction==='asc'?comparison:-comparison):a.index-b.index}).map(item=>item.record)}
function paginateTts(records){const pages=Math.max(1,Math.ceil(records.length/tableState.pageSize));tableState.page=Math.max(1,Math.min(tableState.page,pages));const start=(tableState.page-1)*tableState.pageSize;return {rows:records.slice(start,start+tableState.pageSize),pages,start,end:Math.min(start+tableState.pageSize,records.length)}}
