function render(){renderIntegrationLocations();$('serviceCode').value=serviceCode;$('typeLK2').checked=parameterType==='LK2';$('typeVP8').checked=parameterType==='VP8';$('parameterTypeInfo').textContent=parameterType?'Tipo selecionado: '+parameterType+' • aplica-se a todo o conjunto atual.':'Selecione LK2 ou VP8 antes de importar e revisar a prévia SQL.';const records=ttRecords();renderBulkMarkings(records);const pending=records.filter(record=>!record.rows.some(r=>isPositiveGuard(r,r.ATRIBUTO_VALOR))).map(record=>record.tt);$('autoRuleInfo').textContent=!records.length?'Importe uma planilha ou carregue o exemplo para começar.':pending.length?'Condição de valor > 0 pendente para: '+pending.join(', ')+'. Corrija os dados contábeis para gerar automaticamente.':'Todos os Transtypes possuem a condição obrigatória de valor > 0. Regras ausentes são incluídas automaticamente.';const ok=records.filter(record=>!record.errors.length).length;$('valid').textContent=ok;$('invalid').textContent=records.length-ok;$('systems').textContent=records.length;$('count').textContent=records.length;const visible=visibleTts(records);$('export').disabled=!visible.length;const pagination=paginateTts(visible);$('rows').innerHTML=pagination.rows.map(ttTableRow).join('')||'<tr><td colspan="15">Nenhum Transtype encontrado.</td></tr>';$('shown').textContent=visible.length?`Exibindo ${pagination.start+1}–${pagination.end} de ${visible.length} Transtypes${visible.length!==records.length?' (total: '+records.length+')':''}`:'Nenhum Transtype encontrado';$('pageSize').value=String(tableState.pageSize);$('pageInfo').textContent='Página '+tableState.page+' de '+pagination.pages;$('firstPage').disabled=$('previousPage').disabled=tableState.page===1;$('nextPage').disabled=$('lastPage').disabled=tableState.page===pagination.pages;for(const button of $('paramHeader').querySelectorAll('[data-sort]')){const active=button.dataset.sort===tableState.sortKey;button.closest('th').setAttribute('aria-sort',active?(tableState.direction==='asc'?'ascending':'descending'):'none');button.querySelector('.sort-indicator').textContent=active?(tableState.direction==='asc'?'↑':'↓'):'↕'}}
$('search').oninput=()=>{tableState.page=1;render()};$('filter').onchange=()=>{tableState.page=1;render()};$('rows').onclick=event=>{if(event.target.closest('[data-exclude], [data-pilot]'))return;const row=event.target.closest('tr[data-tt]');if(row)editTt(row.dataset.tt)};$('rows').onkeydown=event=>{if(event.key==='Enter'&&event.target.matches('tr[data-tt]')){event.preventDefault();event.target.click()}};
$('paramHeader').onclick=event=>{const button=event.target.closest('[data-sort]');if(!button)return;const key=button.dataset.sort;tableState.direction=tableState.sortKey===key&&tableState.direction==='asc'?'desc':'asc';tableState.sortKey=key;tableState.page=1;render()};
$('pageSize').onchange=()=>{const size=Number($('pageSize').value);if([10,50,100].includes(size)){tableState.pageSize=size;tableState.page=1;render()}};$('firstPage').onclick=()=>{tableState.page=1;render()};$('previousPage').onclick=()=>{tableState.page--;render()};$('nextPage').onclick=()=>{tableState.page++;render()};$('lastPage').onclick=()=>{tableState.page=Math.max(1,Math.ceil(visibleTts().length/tableState.pageSize));render()};
let ttDraft=null;
