function headerIndex(){return Math.max(0,Math.min(9999,(parseInt($('headerRow').value,10)||1)-1))}
function renderSharedFields(){closeFieldPicker();$('ttSharedFields').innerHTML=['transtype','DESCRICAO_TRANSTYPE','ATRIBUTO_DATA','ATRIBUTO_VALOR','EMPRESA','DEPARTAMENTO DEBITO','DEPARTAMENTO CREDITO','CONTA DEBITO','CONTA CREDITO'].map(k=>{const i=meta.indexOf(k),value=ttDraft.shared[k],dynamic=['EMPRESA','DEPARTAMENTO DEBITO','DEPARTAMENTO CREDITO'].includes(k),fixed=dynamic&&(ttDraft.valueModes?.[k]?ttDraft.valueModes[k]==='fixed':(!value||/^[\d./]+$/.test(value))),picker=['ATRIBUTO_DATA','ATRIBUTO_VALOR'].includes(k)||(dynamic&&!fixed),mode=dynamic?`<div class="value-settings"><select class="value-mode" aria-label="Tipo de ${esc(sharedLabels[k])}" data-value-mode="${esc(k)}"><option value="fixed" ${fixed?'selected':''}>Valor fixo</option><option value="field" ${!fixed?'selected':''}>Campo do layout</option></select></div>`:'';return `<div class="tt-shared-picker ${k==='EMPRESA'?'tt-company-field':''}"><span class="shared-field-label">${esc(sharedLabels[k])}</span>${mode}${picker?fieldPickerHtml('shared-'+i,'tt_shared_'+i,value,sharedLabels[k],'Pesquisar '+sharedLabels[k],'data-shared="'+k+'"'):`<input id="tt_shared_${i}" data-shared="${esc(k)}" aria-label="${esc(sharedLabels[k])}" required value="${esc(value)}">`}<small class="tt-inline-error" id="tt_shared_error_${i}"></small></div>`}).join('')}
$('ttSharedFields').onchange=event=>{const mode=event.target.closest('[data-value-mode]');if(mode){captureTtDraft();const k=mode.dataset.valueMode;ttDraft.valueModes=ttDraft.valueModes||{};ttDraft.valueModes[k]=mode.value;ttDraft.shared[k]=mode.value==='field'?'__SELECIONAR_CAMPO__':'';renderSharedFields();if(mode.value==='field'){const i=meta.indexOf(k);$('tt_shared_'+i).value='';ttDraft.shared[k]='';$('tt_field_button_shared-'+i).querySelector('.field-picker-value').textContent='Selecione um campo'}ttFeedback();return}ttFeedback()};
function layoutLinks(id){return projects.filter(p=>p.layoutId===id&&p.rows.length).map(p=>p.name)}
let deletingLayoutId=null;
$('deleteLayout').onclick=()=>{const id=$('layoutEditSelect').value,record=layouts.find(l=>l.id===id);if(!record){$('layoutError').textContent='Selecione um layout cadastrado para excluir.';return}saveCurrentProject();const links=layoutLinks(id);if(links.length){$('layoutError').textContent='Layout utilizado nos projetos: '+links.join(', ')+'. Selecione outro layout nesses projetos antes de excluir.';return}deletingLayoutId=id;$('deleteLayoutConfirmation').value='';$('deleteLayoutError').textContent='';$('confirmDeleteLayout').disabled=true;$('deleteLayoutMessage').textContent='O layout "'+record.name+'" será excluído. Esta ação não pode ser desfeita.';$('deleteLayoutDialog').showModal()};
$('deleteLayoutConfirmation').oninput=()=>{$('confirmDeleteLayout').disabled=$('deleteLayoutConfirmation').value!=='EXCLUIR'};
$('cancelDeleteLayout').onclick=()=>$('deleteLayoutDialog').close();
$('deleteLayoutForm').onsubmit=async event=>{event.preventDefault();if($('deleteLayoutConfirmation').value!=='EXCLUIR')return;const id=deletingLayoutId;if(layoutLinks(id).length){$('deleteLayoutError').textContent='O layout está vinculado a parametrizações.';return}const button=$('confirmDeleteLayout');button.disabled=true;try{if(projectLayoutIds.has(id)){const response=await fetch('/api/layouts/'+encodeURIComponent(id),{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmation:'EXCLUIR'})});if(!response.ok)throw Error((await response.json()).error||'Não foi possível excluir o arquivo.');projectLayoutIds.delete(id)}layouts=layouts.filter(l=>l.id!==id);for(const p of projects)if(p.layoutId===id)p.layoutId='';if(selectedLayout===id)selectedLayout='';saveLayouts();persist();$('layoutEditSelect').value='';layoutDraftRecord=null;refreshLayoutOptions();fillLayoutForm();render();$('deleteLayoutDialog').close();toast('Layout excluído.')}catch(e){$('deleteLayoutError').textContent=e.message}finally{button.disabled=$('deleteLayoutConfirmation').value!=='EXCLUIR'}};
renderProjects();



function renderBulkMarkings(records){const codes=records.map(r=>r.tt),count=codes.length,pilots=codes.filter(code=>pilotTranstypes.has(code)).length,excluded=codes.filter(code=>excludedTranstypes.has(code)).length;$('pilotAll').disabled=!count||pilots===count;$('pilotNone').disabled=!pilots;$('excludeAll').disabled=!count||excluded===count;$('excludeNone').disabled=!excluded;$('bulkMarkingScope').textContent='Todos os '+count+' Transtypes do projeto, incluindo outras páginas e registros filtrados. Piloto: '+pilots+' · Exclusão: '+excluded+'.'}
function setAllMarkings(kind,checked){const codes=ttRecords().map(record=>record.tt),marks=kind==='pilot'?pilotTranstypes:excludedTranstypes;for(const code of codes)checked?marks.add(code):marks.delete(code);persist();render();toast((checked?'Marcados':'Desmarcados')+' '+codes.length+' Transtypes para '+(kind==='pilot'?'piloto':'exclusão')+'.')}
$('pilotAll').onclick=()=>setAllMarkings('pilot',true);$('pilotNone').onclick=()=>setAllMarkings('pilot',false);$('excludeAll').onclick=()=>setAllMarkings('excluded',true);$('excludeNone').onclick=()=>setAllMarkings('excluded',false);

function positionFieldPicker(){if(!openFieldPickerId)return;const button=$('tt_field_button_'+openFieldPickerId),popup=$('tt_field_popup_'+openFieldPickerId);if(!button||!popup)return;const rect=button.getBoundingClientRect(),height=Math.min(320,window.innerHeight-24),width=Math.min(Math.max(rect.width,290),window.innerWidth-24),below=window.innerHeight-rect.bottom;popup.style.width=width+'px';popup.style.maxHeight=height+'px';popup.style.left=Math.max(12,Math.min(rect.left,window.innerWidth-width-12))+'px';popup.style.top=Math.max(12,Math.min(below<height?rect.top-height:rect.bottom+4,window.innerHeight-height-12))+'px'}

let deletingProjectId=null;
function openDeleteProject(id){const project=projects.find(p=>p.id===id);if(!project)return;deletingProjectId=id;$('deleteProjectConfirmation').value='';$('confirmDeleteProject').disabled=true;$('deleteProjectError').textContent='';$('deleteProjectMessage').textContent='Excluir o projeto "'+project.name+'" e seus '+new Set(project.rows.map(r=>r.transtype)).size+' Transtypes? As parametrizações e marcações desse projeto serão apagadas. Os layouts serão mantidos para reutilização. Esta ação não pode ser desfeita.';$('deleteProjectDialog').showModal()}
function removeProject(id,confirmation){if(confirmation!=='EXCLUIR')throw Error('Digite exatamente EXCLUIR.');if(!projects.some(p=>p.id===id))throw Error('Projeto não encontrado.');saveCurrentProject();const remaining=projects.filter(p=>p.id!==id),selected=remaining.some(p=>p.id===currentProjectId)?currentProjectId:remaining[0]?.id||null;localStorage.setItem('conecta-projects-v1',JSON.stringify({schemaVersion:1,selectedId:selected,projects:remaining}));projects=remaining;restoreProject(selected);persist();tableState.page=1;renderLayouts();render();showProjects()}
$('deleteProjectConfirmation').oninput=()=>{$('confirmDeleteProject').disabled=$('deleteProjectConfirmation').value!=='EXCLUIR'};
$('cancelDeleteProject').onclick=()=>$('deleteProjectDialog').close();
$('deleteProjectForm').onsubmit=event=>{event.preventDefault();try{removeProject(deletingProjectId,$('deleteProjectConfirmation').value);$('deleteProjectDialog').close();deletingProjectId=null;toast('Projeto excluído. Os layouts foram mantidos.')}catch(error){$('deleteProjectError').textContent=error.message}};
